import { createSlice, createAsyncThunk, PayloadAction } from "@reduxjs/toolkit";
import { fetchCartItems, increaseCartItemQuantity, decreaseCartItemQuantity, removeCartItem } from "@/services/cartService";

interface CartItem {
  cartItemId: number;
  quantity: number;
  totalAmount: number;
  cartId: number;
  productId: number;
  productName: string;
  productImage: string;
  productPrice: number;
}

interface CartState {
  items: CartItem[];
  loading: boolean;
  error: string | null;
}

const initialState: CartState = {
  items: [],
  loading: false,
  error: null,
};

// Fetch cart items from API
export const fetchCart = createAsyncThunk("cart/fetchCart", async (accessToken: string, { rejectWithValue }) => {
  try {
    return await fetchCartItems(accessToken);
  } catch (err: any) {
    return rejectWithValue(err.response?.data?.message || err.message);
  }
});

// Increase item quantity
export const increaseQuantity = createAsyncThunk(
  "cart/increaseQuantity",
  async ({ productId, accessToken }: { productId: number; accessToken: string | null }, { dispatch }) => {
    await increaseCartItemQuantity(productId, accessToken);
    dispatch(fetchCart(accessToken!));
  }
);

// Decrease item quantity
export const decreaseQuantity = createAsyncThunk(
  "cart/decreaseQuantity",
  async ({ productId, accessToken }: { productId: number; accessToken: string | null }, { dispatch }) => {
    await decreaseCartItemQuantity(productId, 1, accessToken);
    dispatch(fetchCart(accessToken!));
  }
);

// Remove item from cart
export const removeItem = createAsyncThunk(
  "cart/removeItem",
  async ({ cartItemId, accessToken }: { cartItemId: number; accessToken: string | null }, { dispatch }) => {
    await removeCartItem(cartItemId, accessToken);
    dispatch(fetchCart(accessToken!));
  }
);

const cartSlice = createSlice({
  name: "cart",
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchCart.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchCart.fulfilled, (state, action: PayloadAction<CartItem[]>) => {
        state.loading = false;
        state.items = action.payload;
      })
      .addCase(fetchCart.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
        state.items = [];
      });
  },
});

export default cartSlice.reducer;
